import React, { useEffect, useState } from "react";
import { motion } from "framer-motion";

const WorkerSplash = ({ onComplete }) => {
  const [isExiting, setIsExiting] = useState(false);

  useEffect(() => {
    const timer = setTimeout(() => setIsExiting(true), 3000);
    const finish = setTimeout(onComplete, 3800);
    return () => { clearTimeout(timer); clearTimeout(finish); };
  }, [onComplete]);

  return (
    <div className="h-screen w-full bg-[#FDFAD8] flex items-center justify-center relative overflow-hidden font-sans">

      {/* 1. THE DOORS (Transition Layers) */}
      {isExiting && (
        <>
          <div className="absolute inset-y-0 left-0 w-1/2 bg-[#47510B] z-50 animate-door-left" />
          <div className="absolute inset-y-0 right-0 w-1/2 bg-[#47510B] z-50 animate-door-right" />
        </>
      )}

      {/* 2. THE MECHANICAL "T2T" UNIT */}
      <div className="flex flex-col items-center">
        <div className="flex items-center">
          {/* First T */}
          <motion.span 
            initial={{ y: -500, opacity: 0 }}
            animate={{ y: 0, opacity: 1 }}
            transition={{ type: "spring", damping: 12, stiffness: 100, delay: 0.2 }}
            className="text-[12rem] md:text-[18rem] font-[1000] text-[#47510B] leading-none tracking-tighter"
          >
            T
          </motion.span>

          {/* The 2 - The "Piston" */}
          <motion.div 
            initial={{ scale: 0 }}
            animate={{ scale: 1 }}
            transition={{ type: "spring", damping: 8, stiffness: 200, delay: 0.5 }}
            className="bg-[#FF5B03] w-24 h-24 md:w-40 md:h-40 flex items-center justify-center border-[8px] border-[#47510B] rotate-12 shadow-[8px_8px_0px_#CAD23C]"
          >
            <span className="text-white text-7xl md:text-9xl font-black italic">2</span>
          </motion.div>

          {/* Second T */}
          <motion.span 
            initial={{ y: 500, opacity: 0 }}
            animate={{ y: 0, opacity: 1 }}
            transition={{ type: "spring", damping: 12, stiffness: 100, delay: 0.3 }}
            className="text-[12rem] md:text-[18rem] font-[1000] text-[#47510B] leading-none tracking-tighter"
          >
            T
          </motion.span>
        </div>

        {/* 3. WORKER IDENTIFIER */}
        <motion.div 
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={{ delay: 1.2 }}
          className="mt-[-20px] bg-[#47510B] px-8 py-2 transform -skew-x-12"
        >
          <h2 className="text-[#FFF24D] font-black text-2xl italic tracking-[0.3em]">
            WORKER_SYSTEM
          </h2>
        </motion.div>

        {/* 4. TACTICAL PROGRESS */}
        <div className="mt-12 flex gap-2">
          {[...Array(4)].map((_, i) => (
            <motion.div 
              key={i}
              initial={{ backgroundColor: "#CAD23C" }}
              animate={{ backgroundColor: ["#CAD23C", "#FF5B03", "#CAD23C"] }}
              transition={{ duration: 0.8, repeat: Infinity, delay: i * 0.2 }}
              className="w-3 h-8 border-2 border-[#47510B]"
            />
          ))}
        </div>
      </div>

      {/* 5. THE "HEAVY LOAD" TEXT */}
      <div className="absolute bottom-10 w-full text-center">
        <p className="text-[#47510B] font-bold text-[10px] tracking-[1em] opacity-40">
          LOGISTICS_GEAR_ENGAGED
        </p>
      </div>
    </div>
  );
};

export default WorkerSplash;
